import jakarta.persistence.Column;
import jakarta.persistence.MappedSuperclass;
import jakarta.validation.constraints.NotBlank;
@MappedSuperclass
public class NamedEntity extends BaseEntity {
	@Column
	@NotBlank
	private String name;
	public String getName() {
		return this.name;
	}
